			paths: [join(client, "src", "Page.svelte"), join(cwd, "src", "app.ts"), join(cwd, "src", "lib.rs")],
			lintDir,
			scanProject: false,
		});
		const dlint = plan.jobs.filter((job) => job.name === "dlint");
		expect(dlint.map((job) => [job.cwd, job.command, job.args])).toEqual([
