test("CLI reports an empty plan as JSON and exits 0", () => {
	const cwd = tempDir();
	try {
		const run = Bun.spawnSync([process.execPath, join(import.meta.dir, "lint-files.ts"), "--json", "--cwd", cwd], {
			cwd,
