	if (groups.size > 0 || scan) {
		if (!exists(dlint)) notes.push("dlint: missing lint/dlint");
		else if (scan) {
			jobs.push({ name: "dlint", command: dlint, args: ["--quiet", "."], cwd: input.cwd, timeout: DLINT_TIMEOUT_MS });
		} else {
			for (const [pkg, files] of groups) {
				jobs.push({
					name: "dlint",
					command: dlint,
