	expect(isCodeSource("/proj/Page.svelte")).toBe(true);
	expect(isCodeSource("/proj/layout.css")).toBe(true);
	expect(isCodeSource("/proj/data.json")).toBe(false);
	expect(isCodeSource("/proj/lib.rs")).toBe(false);
