edits.newText:
export function hasPackageTable(toml: string): boolean {
	return /^\[package\]\s*$/m.test(toml);
}

/** Scaffold manifests keep a `{{PLACEHOLDER}}` package name; cargo cannot build them. */
function isTemplatePackage(toml: string): boolean {
	const name = /^name\s*=\s*"([^"]*)"/m.exec(toml)?.[1];
	return name !== undefined && name.includes("{{");
}

export function findCargoPackageDir(
	filePath: string,
	exists: Exists = existsSync,
	readFile: ReadFile = readUtf8,
): string | undefined {
	for (let dir = dirname(filePath); ; dir = dirname(dir)) {
		const manifest = join(dir, "Cargo.toml");
		if (exists(manifest)) {
			const toml = readFile(manifest);
			// A template crate is not lintable, and must not fall through to the crate that contains it.
			if (hasPackageTable(toml)) return isTemplatePackage(toml) ? undefined : dir;
		}
		if (dirname(dir) === dir) return undefined;
	}
}

